// Tables are sorted by name, compared case-insensitively.
template <std::size_t N>
inline const RetailEntityClass *FindRetailEntityClass(const RetailEntityClass (&table)[N], const char *name) {
    for (const RetailEntityClass &entry : table)
        if (striEqual(entry.name, name)) return &entry;
    return nullptr;
}

